  "implementation": "def solve(case):
    if not isinstance(case, dict) or 'lines' not in case:
        raise ValueError('Invalid case: missing "lines"')
    lines = case['lines']
    if not isinstance(lines, list) or len(lines) == 0:
        raise ValueError('Invalid case: "lines" must be a non-empty list')
    valid_types = {'thought', 'action', 'action_input', 'observation', 'final'}
    trajectory = []
    expected = {'thought'}
    error_line = None
    for i, line in enumerate(lines, start=1):
        line = line.strip()
        if not line:
            error_line = i
            break
        colon_pos = line.find(':')
        if colon_pos == -1:
            error_line = i
            break
        raw_type = line[:colon_pos].strip()
        content = line[colon_pos+1:].strip()
        rec_type = raw_type.lower()
        if rec_type not in valid_types or rec_type not in expected:
            error_line = i
            break
        trajectory.append({'type': rec_type, 'content': content})
        if rec_type == 'thought':
            expected = {'action'}
        elif rec_type == 'action':
            expected = {'action_input', 'observation'}
        elif rec_type == 'action_input':
            expected = {'observation'}
        elif rec_type == 'observation':
            expected = {'thought', 'final'}
        elif rec_type == 'final':
            expected = set()
    if error_line is not None:
        valid_prefix = [r for idx, r in enumerate(trajectory, start=1) if idx < error_line]
        return {'valid': False, 'error_line': error_line, 'valid_prefix': valid_prefix}
    if not trajectory or trajectory[-1]['type'] != 'final':
        error_line = len(lines)
        valid_prefix = trajectory[:-1] if trajectory else []
        return {'valid': False, 'error_line': error_line, 'valid_prefix': valid_prefix}
    return {'valid': True, 'trajectory': trajectory}"
